<script>const shell=document.getElementById('app-shell'),toggle=document.getElementById('sidebar-toggle'),sideClose=document.getElementById('sidebar-close'),overlay=document.getElementById('sidebar-overlay');const mobile=()=>window.innerWidth<=960;if(!mobile()&&localStorage.getItem('surya-sidebar-collapsed')==='true')shell.classList.add('sidebar-collapsed');document.documentElement.classList.remove('surya-sidebar-precollapsed');toggle.onclick=()=>{if(mobile()){shell.classList.toggle('sidebar-open')}else{const collapsed=shell.classList.toggle('sidebar-collapsed');localStorage.setItem('surya-sidebar-collapsed',collapsed?'true':'false')}};const closeSide=()=>shell.classList.remove('sidebar-open');sideClose.onclick=closeSide;overlay.onclick=closeSide;window.addEventListener('resize',()=>{if(!mobile())shell.classList.remove('sidebar-open')});
const numberRender=(value,type)=>type==='display'?(value===null||value===''?'–':new Intl.NumberFormat('id-ID').format(Number(value))):value;const percentRender=(value,type)=>{if(type!=='display')return value;if(value===null||value==='')return '–';const n=Number(value);return `${n>0?'+':''}${new Intl.NumberFormat('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1}).format(n)}%`};const canEditOutlet=@json($canEditOutlet);const baseColumns=['id_outlet','nama_outlet','kecamatan','sf','tap','pjp'].map((data,index)=>({data,defaultContent:'-',orderable:false,render:index===0&&canEditOutlet?(value,type)=>type==='display'?`<button class="outlet-profile-link" type="button" data-outlet-id="${String(value).replace(/&/g,'&amp;').replace(/"/g,'&quot;')}">${value}</button>`:value:undefined}));const metricColumns=[];['st_sa','st_pv','cvm','super_seru','comsak','hot_promo','biometrik'].forEach(metric=>{['fm1','m1','mtd','gap','mom_pct'].forEach((period,index)=>{const stock=metric.startsWith('st_');metricColumns.push({data:`${metric}_${period}`,defaultContent:null,orderable:false,className:`metric ${index===0?'group-start ':''}${stock?'sales':'upload'} ${period==='mom_pct'?'mom-value':''}`,render:period==='mom_pct'?percentRender:numberRender})})});const cutoffInput=document.getElementById('sales-cutoff');const table=$('table').DataTable({processing:true,serverSide:true,ordering:false,searchDelay:400,pageLength:25,lengthMenu:[10,25,50,100],dom:'rt<"dt-footer"lip>',ajax:{url:@json(route('surya.outlet-detail.data')),data:d=>{d.tap=document.getElementById('tap-filter').value;d.sales_cutoff=cutoffInput.value}},columns:[...baseColumns,...metricColumns],language:{processing:'Memuat data...',emptyTable:'Outlet PJP tidak ditemukan',zeroRecords:'Data yang dicari tidak ditemukan',info:'Menampilkan _START_–_END_ dari _TOTAL_ outlet',infoEmpty:'Tidak ada data',lengthMenu:'Tampilkan _MENU_',paginate:{previous:'‹',next:'›'}}});const footer=document.querySelector('.dt-footer');if(footer)document.querySelector('.card').appendChild(footer);table.on('draw',()=>{$('.mom-value').each(function(){const n=parseFloat(this.textContent.replace('%','').replace(',','.'));if(!Number.isNaN(n))this.classList.add(n>=0?'positive':'negative')})});const apply=()=>{document.getElementById('cutoff-label').textContent=new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${cutoffInput.value}T00:00:00`));table.search(document.getElementById('outlet-search').value).ajax.reload()};document.getElementById('apply-filter').onclick=apply;document.getElementById('tap-filter').onchange=apply;cutoffInput.onchange=apply;document.getElementById('outlet-search').addEventListener('keydown',e=>{if(e.key==='Enter')apply()});document.getElementById('export-excel').addEventListener('click',function(){const params=new URLSearchParams({q:document.getElementById('outlet-search').value,tap:document.getElementById('tap-filter').value,sales_cutoff:cutoffInput.value});this.href=@json(route('surya.outlet-detail.export'))+'?'+params.toString()});
if(canEditOutlet){const modal=document.getElementById('profile-modal'),form=document.getElementById('profile-form'),message=document.getElementById('profile-message'),save=document.getElementById('profile-save'),profileUrl=@json(route('surya.outlet-detail.profile',['idOutlet'=>'__ID__'])),updateUrl=@json(route('surya.outlet-detail.profile.update',['idOutlet'=>'__ID__']));let activeId='';const closeModal=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true')};document.querySelectorAll('[data-profile-close]').forEach(button=>button.onclick=closeModal);modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});document.querySelector('table').addEventListener('click',async event=>{const button=event.target.closest('[data-outlet-id]');if(!button)return;activeId=button.dataset.outletId;message.textContent='';modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.getElementById('profile-subtitle').textContent='Memuat data outlet...';try{const response=await fetch(profileUrl.replace('__ID__',encodeURIComponent(activeId)),{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Profil outlet gagal dimuat.');const data=await response.json(),outlet=data.outlet;document.getElementById('profile-id').textContent=outlet.id_outlet;document.getElementById('profile-tap').textContent=outlet.tap||'–';document.getElementById('profile-name').textContent=outlet.nama_outlet||'–';document.getElementById('profile-kecamatan').textContent=outlet.kecamatan||'–';document.getElementById('profile-subtitle').textContent='Ubah mapping Sales Force dan hari PJP.';const sf=document.getElementById('profile-sf');sf.innerHTML='<option value="UNMAPPING">UNMAPPING</option>';data.sales.forEach(item=>sf.add(new Option(`${item.namasf} (${item.idsf})`,item.namasf)));sf.value=outlet.sf||'UNMAPPING';const pjp=document.getElementById('profile-pjp');pjp.innerHTML='';data.days.forEach(day=>pjp.add(new Option(day,day)));pjp.value=outlet.pjp||'UNMAPPING'}catch(error){message.textContent=error.message}});form.addEventListener('submit',async event=>{event.preventDefault();message.textContent='';save.disabled=true;try{const response=await fetch(updateUrl.replace('__ID__',encodeURIComponent(activeId)),{method:'PUT',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({sf:document.getElementById('profile-sf').value,pjp:document.getElementById('profile-pjp').value})});const data=await response.json();if(!response.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||data.message||'Perubahan gagal disimpan.');closeModal();table.ajax.reload(null,false)}catch(error){message.textContent=error.message}finally{save.disabled=false}})}
</script>
